9	import {
10	    type StablecoinYieldRootState,
11	    getConvertedOutputTokenBalanceToInputTokenAmount,
12	    selectStablecoinYieldSessionByFlowKey,
13	    stablecoinYieldActions,
14	} from '@suite-common/wallet-core';
15	import { toTokenSymbol } from '@suite-common/wallet-types';
16	import { selectNativeAnalyticsDep } from '@suite-native/analytics';
17	import { Translation } from '@suite-native/intl';
18	import {
19	    type StackNavigationProps,
20	    type YieldStackParamList,
21	    YieldStackRoutes,
22	    useNavigateToInitialScreen,
23	} from '@suite-native/navigation';
24	
25	import { YieldCompleteScreenContent } from '../components/YieldCompleteScreenContent';
26	import { getYieldWithdrawCompleteRows } from '../components/YieldCompleteScreenPresets';
27	import { useResolvedYieldFlowData } from '../hooks/useResolvedYieldFlowData';
28	
29	type RouteProps = RouteProp<YieldStackParamList, YieldStackRoutes.YieldWithdrawComplete>;
30	type NavigationProps = StackNavigationProps<
31	    YieldStackParamList,
32	    YieldStackRoutes.YieldWithdrawComplete
33	>;
