35	export const YieldWithdrawCompleteScreen = () => {
36	    const route = useRoute<RouteProps>();
37	    const navigation = useNavigation<NavigationProps>();
38	    const dispatch = useDispatch();
39	    const navigateToInitialScreen = useNavigateToInitialScreen();
40	    const { CryptoAmountFormatter } = useFormatters();
41	    const { account, flowKey, resolutionStatus, vault } = useResolvedYieldFlowData(route.params);
42	    const flowType = route.params.withdrawFlowType ?? 'withdraw';
43	    const session = useSelector((state: StablecoinYieldRootState) =>
44	        selectStablecoinYieldSessionByFlowKey(state, flowType, flowKey),
45	    );
46	    const isSharesInput = flowType === 'redeem';
47	    const { analytics } = useServices(selectNativeAnalyticsDep);
48	
49	    const handleExit = useCallback(() => {
50	        analytics.report({
51	            type: events.yieldNavigateEvent.name,
52	            payload: {
53	                action: 'continue',
54	                from: 'withdraw-form',
55	                to: 'earn-dashboard',
56	                networkSymbol: account?.symbol,
57	                vaultId: vault?.id,
58	            },
59	        });
60	
61	        if (flowKey) {
62	            dispatch(stablecoinYieldActions.disposeSession({ flowType, flowKey }));
63	        }
64	
65	        navigateToInitialScreen();
66	    }, [
67	        account?.symbol,
68	        analytics,
69	        dispatch,
70	        flowKey,
71	        flowType,
72	        navigateToInitialScreen,
73	        vault?.id,
74	    ]);
75	
76	    useEffect(() => {
77	        if (resolutionStatus !== 'resolved') {
78	            return;
79	        }
80	
81	        if (!session) {
82	            navigateToInitialScreen();
83	
84	            return;
85	        }
86	
87	        if (session.step !== 'complete') {
88	            navigation.replace(YieldStackRoutes.YieldWithdraw, route.params);
89	        }
90	    }, [navigation, navigateToInitialScreen, resolutionStatus, route.params, session]);
91	
92	    const rows = useMemo(() => {
93	        if (resolutionStatus !== 'resolved' || !session || !vault.outputToken) {
94	            return [];
95	        }
96	
97	        const { completedAmount } = session.result;
98	        const underlyingSymbol = toTokenSymbol(vault.token.symbol.toUpperCase());
99	        const vaultTokenSymbol = toTokenSymbol(vault.outputToken.symbol.toUpperCase());
100	        const receivedUnderlyingAmount = isSharesInput
101	            ? getConvertedOutputTokenBalanceToInputTokenAmount({
102	                  networkSymbol: account.symbol,
103	                  token: vault.token,
104	                  outputToken: vault.outputToken,
105	                  outputTokenBalance: completedAmount,
106	                  pricePerShareState: vault.state?.pricePerShareState,
107	              })
108	            : completedAmount;
109	
110	        const receivedAmount = CryptoAmountFormatter.format(receivedUnderlyingAmount, {
111	            symbol: underlyingSymbol,
112	            isBalance: true,
113	            withSymbol: true,
114	            isEllipsisAppended: false,
115	            maxDisplayedDecimals: 8,
116	        });
117	
118	        const withdrawalAmount = isSharesInput
119	            ? CryptoAmountFormatter.format(completedAmount, {
120	                  symbol: vaultTokenSymbol,
121	                  isBalance: true,
122	                  withSymbol: true,
123	                  isEllipsisAppended: false,
124	                  maxDisplayedDecimals: 8,
125	              })
126	            : undefined;
127	
128	        return getYieldWithdrawCompleteRows({
129	            accountSymbol: account.symbol,
130	            receivedAmount,
131	            receivedTokenContract: vault.token.address ?? undefined,
132	            withdrawalAmount,
133	            withdrawalTokenContract: vault.outputToken.address ?? undefined,
134	        });
135	    }, [CryptoAmountFormatter, account, isSharesInput, resolutionStatus, session, vault]);
136	
137	    if (resolutionStatus !== 'resolved' || session?.step !== 'complete') {
138	        return null;
139	    }
140	
141	    return (
142	        <YieldCompleteScreenContent
143	            buttonTranslationId="earn.yieldCompleteScreen.backToOverview"
144	            onButtonPress={handleExit}
145	            rows={rows}
146	            title={<Translation id="earn.yieldWithdrawCompleteScreen.title" />}
147	            subtitle={<Translation id="earn.yieldWithdrawCompleteScreen.subtitle" />}
148	        />
149	    );
150	};
